/**
 * The browser-key registry (plan Phase 2, §7.5).
 *
 * The Data page's key list must be GENERATED by enumerating the keys the code
 * actually writes, never hand-maintained — otherwise a third key added in month
 * three silently makes "What this site knows about you" false again.
 *
 * This registry covers storage KEYS. It deliberately does not reach the fields
 * inside `wys:v1`; those rows derive from the declared schema field set
 * (`WYS_DATA_PAGE_ROWS` in `./local-state.ts`), which is the only way the
 * artboard's "Generated from what's actually stored right now" stays true.
 *
 * Pure data. No React, no CSS, no component import.
 */

import { WYS_KEY_PREFIX, WYS_STORAGE_KEY } from "./local-state";

/**
 * `bct_analytics_consent` is written by `components/ConsentBanner.tsx:7`, which
 * is frozen apart from `try/catch` hardening — its `const storageKey` literal
 * is asserted byte-present by `tests/analytics-frozen.test.ts`. The literal is
 * repeated here rather than imported, and `tests/wys-local-state.test.ts`
 * asserts the two agree by reading the component off disk.
 */
export const CONSENT_STORAGE_KEY = "bct_analytics_consent";

export interface BrowserKeyRecord {
  key: string;
  /** Which surface owns it. */
  owner: "watch-your-step" | "site" | "developer-forward";
  /** The module that writes it — the thing that makes this registry checkable. */
  writtenBy: string;
  /** What it holds, in plain terms, for the Data page. */
  holds: string;
  /** Whether `clearAllWysData()` removes it. */
  clearedByWysClear: boolean;
}

/**
 * The Developer Forward Lite dataset key, from the stamped `storage.key`.
 *
 * `clearedByWysClear: false` is the whole point of the field here. Two products
 * now write local data on this origin and NEITHER may sweep the other's:
 * `wysOwnedKeys()` filters on `WYS_KEY_PREFIX` (`wys:`), and this key does not
 * carry that prefix, so a Watch Your Step clear cannot touch a learner's Trust
 * Forward ledger and Developer Forward's own reset cannot touch Watch Your Step.
 */
export const DEVELOPER_FORWARD_STORAGE_KEY = "benchantech:developer-forward-lite:state";

/**
 * The Developer Forward Lite YY ledger key, from `DEVELOPER_FORWARD_YY_STORAGE_KEY` in
 * `lib/developer-forward/yy/records.ts`.
 *
 * A FOURTH KEY, AND A SECOND ONE FOR THE SAME PRODUCT. It is not nested inside
 * the v1 dataset because that dataset's serializer drops every undeclared
 * top-level key by design, so a nested YY stream would be deleted on the first
 * v1 write. Two keys, two sanitizers, one origin — and therefore two registry
 * rows, because this registry is about what is STORED, not about how many
 * products store it.
 *
 * `clearedByWysClear: false`, for the same reason the v1 row carries it:
 * `wysOwnedKeys()` filters on `WYS_KEY_PREFIX` (`wys:`) and this key carries
 * the `benchantech:` namespace instead, so a Watch Your Step clear cannot reach
 * a learner's YY judgment ledger. That ledger is the one dataset in the product
 * that must not be swept by another surface's reset: it holds decisions that
 * were committed BEFORE Ben's judgment was revealed, and the whole epistemic
 * claim of the YY Method is that later information never overwrites them.
 * `clearYYLedger()` removes this key and only this key, and the confirmation is
 * the caller's.
 *
 * THE LITERAL IS RESTATED RATHER THAN IMPORTED, exactly as the v1 key above is.
 * `records.ts` reaches `@/lib/developer-forward/ledger`, `/session` and `/storage`;
 * importing it here would pull the whole YY machinery into `/privacy`,
 * `/cookies` and the Data page, all of which need the NAME of the key and
 * nothing else. `tests/wys-local-state.test.ts` reads `records.ts` off disk and
 * asserts the two literals are byte-identical, which is the same mechanism that
 * keeps `CONSENT_STORAGE_KEY` and the frozen `ConsentBanner` literal in step.
 */
export const DEVELOPER_FORWARD_YY_STORAGE_KEY = "benchantech:developer-forward-lite:yy";

export const BROWSER_KEYS: readonly BrowserKeyRecord[] = [
  {
    key: WYS_STORAGE_KEY,
    owner: "watch-your-step",
    writtenBy: "lib/wys/local-state.ts",
    holds: "onboarding choices, curriculum progress, kept judgments, the rulebook, deeper-practice interest and the last course route",
    clearedByWysClear: true
  },
  {
    key: DEVELOPER_FORWARD_STORAGE_KEY,
    owner: "developer-forward",
    writtenBy: "lib/developer-forward/storage.ts",
    holds:
      "your five-case answers, the immutable local ledger of what you did, any optional notes you wrote, your optional local handle, unsent drafts and the derived result",
    clearedByWysClear: false
  },
  {
    key: DEVELOPER_FORWARD_YY_STORAGE_KEY,
    owner: "developer-forward",
    writtenBy: "lib/developer-forward/yy/records.ts",
    holds:
      "the judgment you committed at each case checkpoint, the option you named as your closest alternative, any optional notes you wrote before or after committing, and the time and run each one belongs to",
    clearedByWysClear: false
  },
  {
    key: CONSENT_STORAGE_KEY,
    owner: "site",
    writtenBy: "components/ConsentBanner.tsx",
    holds: "whether analytics cookies were allowed or declined on this device",
    clearedByWysClear: false
  }
];

export const BROWSER_KEY_NAMES: readonly string[] = BROWSER_KEYS.map((record) => record.key);

/** The keys `clearAllWysData()` sweeps. Everything under the `wys:` prefix. */
export function wysOwnedKeys(): string[] {
  return BROWSER_KEYS.filter((record) => record.key.startsWith(WYS_KEY_PREFIX)).map((record) => record.key);
}

/** The keys that deliberately SURVIVE a Watch Your Step clear (§7.4). */
export function keysSurvivingWysClear(): string[] {
  return BROWSER_KEYS.filter((record) => !record.clearedByWysClear).map((record) => record.key);
}
